type TicketPreview = { id: number; title: string; status: "OPEN" | "CLOSED" };
function openTitles(tickets: TicketPreview[]) {
  const titles = tickets.filter(t => t.status === "OPEN").map(t => t.title);
  const first = tickets.find(t => t.id === 42);
  return { titles, firstTitle: first?.title ?? "Brak" };
}
const result = openTitles([
  { id: 1, title: "Login", status: "CLOSED" },
  { id: 42, title: "Eksport", status: "OPEN" },
  { id: 3, title: "API", status: "OPEN" },
]);
console.log(result); // { titles: ["Eksport", "API"], firstTitle: "Eksport" }

